QString appDir() { auto p=QStandardPaths::writableLocation(QStandardPaths::AppLocalDataLocation); QDir().mkpath(p); return p; }
QString historyPath() { return appDir()+"/history.json"; }
QString logPath() { return appDir()+"/d1vi.log"; }
QString fmtBytes(quint64 n) { const QStringList u={"B","KB","MB","GB","TB"}; double x=double(n); int i=0; while(x>=1024&&i<u.size()-1){x/=1024;++i;} return (i?QString::number(x,'f',1):QString::number(quint64(x)))+" "+u[i]; }
QString colorFor(double v) { return v>85?"#f87171":v>65?"#fbbf24":"#52d6a5"; }
struct GpuPreferenceState { bool ok=false,exists=false; QString value; LONG error=ERROR_SUCCESS; };
GpuPreferenceState readGpuPreference(const QString& executable){GpuPreferenceState s;HKEY key{};LONG e=RegOpenKeyExW(HKEY_CURRENT_USER,L"Software\\Microsoft\\DirectX\\UserGpuPreferences",0,KEY_QUERY_VALUE,&key);if(e==ERROR_FILE_NOT_FOUND){s.ok=true;return s;}if(e!=ERROR_SUCCESS){s.error=e;return s;}auto name=executable.toStdWString();DWORD type=0,size=0;e=RegQueryValueExW(key,name.c_str(),nullptr,&type,nullptr,&size);if(e==ERROR_FILE_NOT_FOUND){s.ok=true;RegCloseKey(key);return s;}if(e!=ERROR_SUCCESS){s.error=e;RegCloseKey(key);return s;}if(type!=REG_SZ&&type!=REG_EXPAND_SZ){s.error=ERROR_DATATYPE_MISMATCH;RegCloseKey(key);return s;}std::vector<wchar_t> value(size/sizeof(wchar_t)+1,0);e=RegQueryValueExW(key,name.c_str(),nullptr,&type,reinterpret_cast<BYTE*>(value.data()),&size);if(e==ERROR_SUCCESS){s.ok=true;s.exists=true;s.value=QString::fromWCharArray(value.data());}else s.error=e;RegCloseKey(key);return s;}
QString gpuPreferenceLabel(const QString& raw){QString setting;for(const auto&part:raw.split(';'))if(part.trimmed().startsWith("GpuPreference=",Qt::CaseInsensitive))setting=part.section('=',1).trimmed();if(setting=="2")return "High performance";if(setting=="1")return "Power saving";if(setting=="0"||setting.isEmpty())return "Let Windows decide";return "Unknown preference ("+setting+")";}
QString withGpuPreference(const QString& raw,int preference){QStringList parts;for(const auto&part:raw.split(';',Qt::SkipEmptyParts))if(!part.trimmed().startsWith("GpuPreference=",Qt::CaseInsensitive))parts<<part.trimmed();parts<<"GpuPreference="+QString::number(preference);return parts.join(';')+";";}
bool processIsElevated(){HANDLE token{};if(!OpenProcessToken(GetCurrentProcess(),TOKEN_QUERY,&token))return false;TOKEN_ELEVATION elevation{};DWORD size=sizeof(elevation);BOOL ok=GetTokenInformation(token,TokenElevation,&elevation,sizeof(elevation),&size);CloseHandle(token);return ok&&elevation.TokenIsElevated;}

struct Snapshot { FILETIME idle{},kernel{},user{}; bool valid=false; };
class Monitor {
    Snapshot prev; ULONGLONG diskRead=0,diskWrite=0;bool diskPrevious=false;QElapsedTimer diskClock;PDH_HQUERY gpuQuery=nullptr;PDH_HCOUNTER gpuCounter=nullptr;
public:
    struct Data { double cpu=0,gpuPeakEngine=-1; MEMORYSTATUSEX mem{}; SYSTEM_POWER_STATUS power{}; QString cpuName="Unknown CPU",cpuFrequency="Frequency unavailable",plan="Unavailable",planGuid; QStringList gpuNames; quint64 readRate=0,writeRate=0; bool diskOk=false,gpuOk=false; };
    Monitor(){memset(&prev,0,sizeof(prev));diskClock.start(); HKEY k{}; if(RegOpenKeyExW(HKEY_LOCAL_MACHINE,L"HARDWARE\\DESCRIPTION\\System\\CentralProcessor\\0",0,KEY_QUERY_VALUE,&k)==ERROR_SUCCESS){wchar_t b[512]{};DWORD n=sizeof(b); if(RegQueryValueExW(k,L"ProcessorNameString",nullptr,nullptr,reinterpret_cast<BYTE*>(b),&n)==ERROR_SUCCESS) cpuName=QString::fromWCharArray(b).trimmed();DWORD mhz=0;n=sizeof(mhz);if(RegQueryValueExW(k,L"~MHz",nullptr,nullptr,reinterpret_cast<BYTE*>(&mhz),&n)==ERROR_SUCCESS&&mhz)cpuFrequency=QString::number(mhz)+" MHz";RegCloseKey(k);} IDXGIFactory1* factory=nullptr;if(SUCCEEDED(CreateDXGIFactory1(__uuidof(IDXGIFactory1),reinterpret_cast<void**>(&factory)))&&factory){for(UINT i=0;;++i){IDXGIAdapter1* adapter=nullptr;HRESULT e=factory->EnumAdapters1(i,&adapter);if(e==DXGI_ERROR_NOT_FOUND)break;if(FAILED(e)||!adapter)continue;DXGI_ADAPTER_DESC1 desc{};if(SUCCEEDED(adapter->GetDesc1(&desc))&&!(desc.Flags& DXGI_ADAPTER_FLAG_SOFTWARE))gpuNames<<QString::fromWCharArray(desc.Description).trimmed();adapter->Release();}factory->Release();}if(PdhOpenQueryW(nullptr,0,&gpuQuery)==ERROR_SUCCESS){if(PdhAddEnglishCounterW(gpuQuery,L"\\GPU Engine(*)\\Utilization Percentage",0,&gpuCounter)!=ERROR_SUCCESS){PdhCloseQuery(gpuQuery);gpuQuery=nullptr;gpuCounter=nullptr;}} }
    ~Monitor(){if(gpuQuery)PdhCloseQuery(gpuQuery);}
    QString cpuName,cpuFrequency="Frequency unavailable";QStringList gpuNames;
    Data sample(){Data d; d.cpuName=cpuName;d.cpuFrequency=cpuFrequency;d.gpuNames=gpuNames; FILETIME idle{},kernel{},user{}; if(GetSystemTimes(&idle,&kernel,&user)){if(prev.valid){auto delta=[](FILETIME a,FILETIME b){return (ULONGLONG(a.dwHighDateTime)<<32|a.dwLowDateTime)-(ULONGLONG(b.dwHighDateTime)<<32|b.dwLowDateTime);};auto ti=delta(idle,prev.idle),tk=delta(kernel,prev.kernel),tu=delta(user,prev.user),total=tk+tu;if(total)d.cpu=std::clamp(100.0*(double(total-ti)/double(total)),0.0,100.0);}prev={idle,kernel,user,true};}
        d.mem.dwLength=sizeof(d.mem); if(!GlobalMemoryStatusEx(&d.mem)) d.mem.dwMemoryLoad=0; d.power.ACLineStatus=255;if(!GetSystemPowerStatus(&d.power))d.power.ACLineStatus=255;
        GUID* g=nullptr;if(PowerGetActiveScheme(nullptr,&g)==ERROR_SUCCESS&&g){wchar_t name[256]{};DWORD sz=sizeof(name);if(PowerReadFriendlyName(nullptr,g,nullptr,nullptr,reinterpret_cast<BYTE*>(name),&sz)==ERROR_SUCCESS)d.plan=QString::fromWCharArray(name);wchar_t guid[40]{};StringFromGUID2(*g,guid,40);d.planGuid=QString::fromWCharArray(guid);LocalFree(g);}
        IO_COUNTERS io{}; if(GetProcessIoCounters(GetCurrentProcess(),&io)){if(diskPrevious){qint64 ms=std::max<qint64>(1,diskClock.restart());d.readRate=quint64((io.ReadTransferCount-diskRead)*1000/ms);d.writeRate=quint64((io.WriteTransferCount-diskWrite)*1000/ms);}else diskClock.restart();diskRead=io.ReadTransferCount;diskWrite=io.WriteTransferCount;diskPrevious=true;d.diskOk=true;}if(gpuQuery&&gpuCounter&&PdhCollectQueryData(gpuQuery)==ERROR_SUCCESS){DWORD bytes=0,count=0;PDH_STATUS s=PdhGetFormattedCounterArrayW(gpuCounter,PDH_FMT_DOUBLE,&bytes,&count,nullptr);if(s==PDH_MORE_DATA&&bytes){std::vector<BYTE> buf(bytes);auto* items=reinterpret_cast<PDH_FMT_COUNTERVALUE_ITEM_W*>(buf.data());if(PdhGetFormattedCounterArrayW(gpuCounter,PDH_FMT_DOUBLE,&bytes,&count,items)==ERROR_SUCCESS){for(DWORD i=0;i<count;++i)if((items[i].FmtValue.CStatus==PDH_CSTATUS_VALID_DATA||items[i].FmtValue.CStatus==PDH_CSTATUS_NEW_DATA)&&std::isfinite(items[i].FmtValue.doubleValue)){d.gpuPeakEngine=std::max(d.gpuPeakEngine,items[i].FmtValue.doubleValue);d.gpuOk=true;}if(d.gpuOk)d.gpuPeakEngine=std::clamp(d.gpuPeakEngine,0.0,100.0);}}}return d; }
};

class Store {
public:
    static QJsonArray records(){QFile f(historyPath());if(!f.open(QIODevice::ReadOnly))return {};auto doc=QJsonDocument::fromJson(f.readAll());return doc.isArray()?doc.array():QJsonArray{};}
    static bool save(const QJsonArray&a){QFile f(historyPath());if(!f.open(QIODevice::WriteOnly|QIODevice::Truncate))return false;return f.write(QJsonDocument(a).toJson(QJsonDocument::Indented))>=0;}
    static void log(QString level,QString msg){QFile f(logPath());if(f.open(QIODevice::WriteOnly|QIODevice::Append|QIODevice::Text)){f.write((QDateTime::currentDateTime().toString("yyyy-MM-dd HH:mm:ss ")+"["+level+"] "+msg+"\r\n").toUtf8());}}
    static bool setPlan(QString guid){GUID g{};if(CLSIDFromString(reinterpret_cast<LPCOLESTR>(guid.utf16()),&g)!=S_OK)return false;return PowerSetActiveScheme(nullptr,&g)==ERROR_SUCCESS;}
};

QWidget* card(QString title,QString value,QString detail,QColor accent=QColor("#52d6a5")){
    auto *f=new QFrame; f->setObjectName("metricCard");auto*l=new QVBoxLayout(f);l->setContentsMargins(18,15,18,16);l->setSpacing(5);
    auto*t=new QLabel(title.toUpper());t->setObjectName("eyebrow");auto*v=new QLabel(value);v->setObjectName("metricValue");v->setStyleSheet("color:"+accent.name()+";");auto*d=new QLabel(detail);d->setObjectName("muted");d->setWordWrap(true);l->addWidget(t);l->addWidget(v);l->addWidget(d);l->addStretch();return f;
}
QLabel* heading(QString s){auto*l=new QLabel(s);l->setObjectName("pageHeading");return l;}

